# Let's construct a bipartite graph with 15 vertices, girth >= 4 (no triangles), at least 19 edges

# Split into two parts
A = list(range(0, 7))  # 7 vertices
B = list(range(7, 15))  # 8 vertices

edges = []

# Add edges to get at least 19 edges
# Connect vertex 0 to all 8 vertices in B
for b in B:
    edges.append((0, b))

# Connect vertex 1 to all 8 vertices in B
for b in B:
    edges.append((1, b))

# That's 16 edges so far. Need 3 more.
# Connect vertex 2 to 3 vertices in B
for b in B[:3]:
    edges.append((2, b))

print(f"Number of edges: {len(edges)}")
print(f"Edges: {edges}")

# Verify bipartiteness: no edges within A or within B
# Verify no triangles (automatic for bipartite)
# Verify girth >= 4 - need to check no 3-cycles (none in bipartite)
# But also need to check... actually girth >= 4 just means no triangles.

# Let's verify with code
def has_triangle(edges):
    adj = {i: set() for i in range(15)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    for u in range(15):
        for v in adj[u]:
            for w in adj[v]:
                if w != u and w in adj[u]:
                    return True
    return False

print(f"Has triangle: {has_triangle(edges)}")

# Check bipartite
def is_bipartite(edges, n=15):
    adj = {i: [] for i in range(n)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    color = {}
    for start in range(n):
        if start not in color:
            color[start] = 0
            stack = [start]
            while stack:
                u = stack.pop()
                for v in adj[u]:
                    if v not in color:
                        color[v] = 1 - color[u]
                        stack.append(v)
                    elif color[v] == color[u]:
                        return False
    return True

print(f"Is bipartite: {is_bipartite(edges)}")

# Check if there are any cycles
edges = [(0, 7), (0, 8), (0, 9), (0, 10), (0, 11), (0, 12), (0, 13), (0, 14), 
         (1, 7), (1, 8), (1, 9), (1, 10), (1, 11), (1, 12), (1, 13), (1, 14), 
         (2, 7), (2, 8), (2, 9)]

# Build adjacency
adj = {i: [] for i in range(15)}
for u, v in edges:
    adj[u].append(v)
    adj[v].append(u)

# Find shortest cycle using BFS
from collections import deque

def shortest_cycle(adj, n):
    min_cycle = float('inf')
    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent[u]:
                    # Found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

sc = shortest_cycle(adj, 15)
print(f"Shortest cycle length: {sc}")
print(f"Girth >= 4: {sc >= 4 or sc == float('inf')}")
